--
-- Name: artist; Type: TABLE; Schema: public; Owner: echovibe
--

CREATE TABLE public.artist (
    id uuid NOT NULL,
    name character varying(255),
    is_verified boolean NOT NULL,
    is_public boolean NOT NULL,
    real_name character varying(255),
    birth_date date,
    biography text,
    description character varying(255),
    nationality_iso_code character varying(16),
    thumbnail_url character varying(255),
    background_url character varying(255),
    ref_code character varying(100),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_by character varying(255) DEFAULT 'system'::character varying,
    updated_by character varying(255) DEFAULT 'system'::character varying,
    tsv tsvector,
    thumbnail_file_key character varying(255),
    background_file_key character varying(255),
    is_active character varying DEFAULT true NOT NULL,
    tags text[] DEFAULT '{}'::text[] NOT NULL
);


ALTER TABLE public.artist OWNER TO echovibe;

--
-- Name: artist_export; Type: VIEW; Schema: public; Owner: echovibe
--

CREATE VIEW public.artist_export AS
 SELECT name,
    is_verified AS isverified,
    is_public AS ispublic,
    description,
    biography,
    nationality_iso_code AS nationalityisocode,
    thumbnail_url AS thumbnailurl,
    background_url AS backgroundurl,
    ref_code AS refcode,
    to_jsonb(tags) AS tagsjson
   FROM public.artist;


ALTER VIEW public.artist_export OWNER TO echovibe;

