--
-- Name: track_audio_export; Type: VIEW; Schema: public; Owner: echovibe
--

CREATE VIEW public.track_audio_export AS
 SELECT ta0.track_ref_code AS trackrefcode,
    ta0.file_url AS fileurl,
    ta0.quality
   FROM (public.track t0
     JOIN public.track_audio ta0 ON ((t0.id = ta0.track_id)));


ALTER VIEW public.track_audio_export OWNER TO echovibe;

--
-- Name: track_export; Type: VIEW; Schema: public; Owner: echovibe
--

CREATE VIEW public.track_export AS
 SELECT t1.name,
    t1.is_public AS ispublic,
    t1.description,
    t1.released_date AS officialreleaseddate,
    t1.duration_second AS durationsecond,
    t1.is_playable AS isplayable,
    t1.thumbnail_url AS thumbnailurl,
    t1.ref_code AS refcode,
    to_jsonb(t1.tags) AS tagsjson,
    to_jsonb(r0.artist_ref_codes) AS artistrefcodes
   FROM (public.track t1
     JOIN ( SELECT ta0.track_id,
            array_agg(ta0.artist_ref_code) AS artist_ref_codes
           FROM (public.track t0
             JOIN public.track_artist ta0 ON ((t0.id = ta0.track_id)))
          GROUP BY ta0.track_id) r0 ON ((t1.id = r0.track_id)));


ALTER VIEW public.track_export OWNER TO echovibe;

